/** A テーマ in the style settings; `id` is what is saved. */
enum class Theme(val id: String, val displayName: String, val isAlwaysDark: Boolean) {
  Pochical("pochical", "ポチカル", false),
  Zen("zen", "禅", false),
  Sumi("sumi", "墨", false),
  Milktea("milktea", "ミルクティー", false),
  Matcha("matcha", "抹茶", false),
  Cocoa("cocoa", "ココア", false),
  Soda("soda", "ソーダ", false),
  Sakura("sakura", "さくら", false),
  Sumire("sumire", "すみれ", false),
  Kissa("kissa", "喫茶", true),
  Tsukiyo("tsukiyo", "月夜", true),
  Kokuban("kokuban", "黒板", true),
  ;

  fun colors(dark: Boolean): ThemeColors =
    when (this) {
      Pochical -> if (dark) ThemeColors.PochicalDark else ThemeColors.PochicalLight
      Zen -> if (dark) ThemeColors.ZenDark else ThemeColors.ZenLight
      Sumi -> if (dark) ThemeColors.SumiDark else ThemeColors.SumiLight
      Milktea -> if (dark) ThemeColors.MilkteaDark else ThemeColors.MilkteaLight
      Matcha -> if (dark) ThemeColors.MatchaDark else ThemeColors.MatchaLight
      Cocoa -> if (dark) ThemeColors.CocoaDark else ThemeColors.CocoaLight
      Soda -> if (dark) ThemeColors.SodaDark else ThemeColors.SodaLight
      Sakura -> if (dark) ThemeColors.SakuraDark else ThemeColors.SakuraLight
      Sumire -> if (dark) ThemeColors.SumireDark else ThemeColors.SumireLight
      Kissa -> ThemeColors.KissaDark
      Tsukiyo -> ThemeColors.TsukiyoDark
      Kokuban -> ThemeColors.KokubanDark
    }
}

